before:
:root{
  --amt-orange:#e86f1c;
  --amt-orange-soft:#f3a45f;
  --amt-dark:#121419;
  --amt-text:#1b1f25;
  --amt-muted:#636b75;
  --amt-line:#e9e9e9;
  --amt-soft:#f7f7f7;
  --amt-shadow:0 14px 45px rgba(0,0,0,.06);
  --amt-icon:#3a3f46;
  --amt-card-radius:22px;
}

@media (prefers-reduced-motion:no-preference){
  @property --amt-radial-fill{
    syntax:"";
    inherits:false;
    initial-value:0%;
  }
}



.amt-wrapper{
  max-width:1340px;
  margin:0 auto;
  padding:90px 20px;
}

/* HERO */

.amt-hero{
  display:grid;
  grid-template-columns:minmax(0,620px) minmax(420px,1fr);
  gap:70px;
  align-items:center;
  margin-bottom:90px;
}

.amt-title{
  margin:0 0 26px;
  font-size:72px;
  line-height:.96;
  font-weight:800;
  letter-spacing:-3px;
  color:#111;
}

.amt-title span{
  color:var(--amt-orange);
}

.amt-lead{
  margin:0 0 20px;
  font-size:19px;
  line-height:1.9;
  color:#474f5a;
}

.amt-highlight{
  color:var(--amt-orange);
  font-weight:800;
}

.amt-hero-panel{
  position:relative;
  min-height:620px;
  border-radius:30px;
  overflow:hidden;
  background:
    radial-gradient(circle at top right,rgba(232,111,28,.12),transparent 28%),
    linear-gradient(145deg,#f8f8f8,#ffffff);
  border:1px solid var(--amt-line);
  box-shadow:0 30px 90px rgba(0,0,0,.08);
  display:flex;
  align-items:center;
  justify-content:center;
}

.amt-grid-bg{
  position:absolute;
  inset:0;
  background-image:
    linear-gradient(rgba(0,0,0,.035) 1px,transparent 1px),
    linear-gradient(90deg,rgba(0,0,0,.035) 1px,transparent 1px);
  background-size:48px 48px;
}

.amt-core{
  position:relative;
  z-index:2;
  width:390px;
  padding:40px;
  border-radius:28px;
  background:#14161b;
  box-shadow:0 30px 80px rgba(0,0,0,.22);
}

.amt-core-label{
  display:block;
  margin-bottom:12px;
  font-size:13px;
  letter-spacing:.08em;
  text-transform:uppercase;
  color:#9ba1ab;
}

.amt-core-value{
  display:block;
  margin-bottom:26px;
  font-size:64px;
  line-height:1;
  font-weight:800;
  color:#fff;
}

.amt-core-chart{
  height:150px;
  display:flex;
  align-items:flex-end;
  gap:14px;
  padding:18px;
  border-radius:18px;
  background:rgba(255,255,255,.04);
  margin-bottom:24px;
}

.amt-core-chart i{
  flex:1;
  display:block;
  border-radius:12px 12px 0 0;
  background:linear-gradient(180deg,var(--amt-orange),var(--amt-orange-soft));
  box-shadow:0 0 18px rgba(232,111,28,.18);
}

.amt-core-bottom{
  font-size:18px;
  line-height:1.7;
  color:#e7e7e7;
}

/* GRAPHICS */

.amt-graph-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:20px;
  margin:70px 0 90px;
}

.amt-graph-card{
  padding:30px;
  border-radius:var(--amt-card-radius);
  background:#fff;
  border:1px solid var(--amt-line);
  box-shadow:var(--amt-shadow);
  transition:transform .35s ease,box-shadow .35s ease,border-color .35s ease;
}

.amt-graph-card:hover{
  transform:translateY(-5px);
  border-color:rgba(232,111,28,.28);
  box-shadow:0 22px 60px rgba(0,0,0,.09);
}

.amt-graph-card h3{
  margin:0 0 22px;
  font-size:20px;
  color:#111;
}

.amt-card-title{
  display:flex;
  align-items:center;
  gap:12px;
}

.amt-icon{
  width:38px;
  height:38px;
  flex:0 0 38px;
  border-radius:12px;
  background:#f2f3f4;
  color:var(--amt-icon);
  display:inline-flex;
  align-items:center;
  justify-content:center;
}

.amt-icon svg{
  width:21px;
  height:21px;
  stroke:currentColor;
  stroke-width:2;
  fill:none;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.amt-radial{
  --amt-radial-value:100%;
  --amt-radial-fill:0%;
  width:150px;
  height:150px;
  margin:0 auto 18px;
  border-radius:50%;
  background:
    radial-gradient(circle at center,#fff 58%,transparent 59%),
    conic-gradient(var(--amt-orange) var(--amt-radial-fill),#eeeeee 0);
  display:flex;
  align-items:center;
  justify-content:center;
  animation:amtRadialGrow 1.25s cubic-bezier(.2,.75,.2,1) both;
}

.amt-radial span{
  font-size:34px;
  font-weight:800;
  color:#111;
  animation:amtFadeUp .75s ease both;
  animation-delay:.28s;
}

.amt-progress{
  height:14px;
  border-radius:30px;
  overflow:hidden;
  background:#efefef;
}

.amt-progress span{
  display:block;
  height:100%;
  border-radius:30px;
  background:linear-gradient(90deg,var(--amt-orange),var(--amt-orange-soft));
  transform-origin:left;
  animation:amtProgressGrow 1.15s cubic-bezier(.2,.75,.2,1) both;
}

.amt-bars{
  height:160px;
  display:flex;
  align-items:flex-end;
  gap:12px;
  border-bottom:1px solid var(--amt-line);
}

.amt-bars i{
  flex:1;
  display:block;
  border-radius:12px 12px 0 0;
  background:linear-gradient(180deg,var(--amt-orange),var(--amt-orange-soft));
}

.amt-core-chart i,
.amt-bars i{
  transform-origin:bottom;
  animation:amtBarGrow 1.05s cubic-bezier(.2,.75,.2,1) both;
}

.amt-core-chart i:nth-child(2),
.amt-bars i:nth-child(2){animation-delay:.08s}

.amt-core-chart i:nth-child(3),
.amt-bars i:nth-child(3){animation-delay:.16s}

.amt-core-chart i:nth-child(4),
.amt-bars i:nth-child(4){animation-delay:.24s}

.amt-core-chart i:nth-child(5),
.amt-bars i:nth-child(5){animation-delay:.32s}

.amt-graph-value{
  font-size:42px;
  line-height:1;
  font-weight:800;
  color:var(--amt-orange);
  margin:16px 0 10px;
  animation:amtFadeUp .75s ease both;
  animation-delay:.28s;
}

.amt-graph-card p{
  margin:14px 0 0;
  font-size:14px;
  line-height:1.7;
  color:var(--amt-muted);
}

/* SECTION */

.amt-section{
  margin-top:90px;
}

.amt-section-title{
  margin:0 0 18px;
  font-size:48px;
  line-height:1.08;
  font-weight:800;
  letter-spacing:-1px;
  color:#111;
}

.amt-divider{
  width:72px;
  height:4px;
  border-radius:10px;
  background:var(--amt-orange);
  margin-bottom:26px;
}

.amt-section-text{
  max-width:1100px;
  margin:0;
  font-size:18px;
  line-height:1.95;
  color:#525a66;
}

/* PROCESS */

.amt-process{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:24px;
  margin-top:44px;
}

.amt-process-card{
  position:relative;
  padding:34px;
  border-radius:var(--amt-card-radius);
  background:#fff;
  border:1px solid var(--amt-line);
  box-shadow:var(--amt-shadow);
  transition:transform .35s ease,box-shadow .35s ease,border-color .35s ease;
}

.amt-process-card:hover{
  transform:translateY(-5px);
  border-color:rgba(232,111,28,.28);
  box-shadow:0 22px 60px rgba(0,0,0,.09);
}

.amt-process-number{
  width:54px;
  height:54px;
  border-radius:50%;
  background:#2f343b;
  color:#fff;
  display:flex;
  align-items:center;
  justify-content:center;
  font-weight:800;
  margin-bottom:22px;
  box-shadow:inset 0 -3px 0 rgba(232,111,28,.45);
}

.amt-process-card h3{
  margin:0 0 16px;
  font-size:24px;
  line-height:1.2;
}

.amt-process-card p{
  margin:0;
  font-size:15px;
  line-height:1.8;
  color:#5b6370;
}

/* APPLICATIONS */

.amt-app-grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:22px;
  margin-top:40px;
}

.amt-app{
  padding:32px;
  border-radius:var(--amt-card-radius);
  background:#fff;
  border:1px solid var(--amt-line);
  box-shadow:var(--amt-shadow);
  transition:transform .35s ease,box-shadow .35s ease,border-color .35s ease;
}

.amt-app:hover{
  transform:translateY(-5px);
  border-color:rgba(232,111,28,.28);
  box-shadow:0 22px 60px rgba(0,0,0,.09);
}

.amt-app h3{
  margin:0 0 16px;
  font-size:28px;
  line-height:1.2;
}

.amt-app p{
  margin:0;
  font-size:16px;
  line-height:1.85;
  color:#59606d;
}

/* IMAGE GRID */

.amt-image-grid{
  display:grid;
  grid-template-columns:repeat(5,1fr);
  gap:18px;
  margin-top:44px;
}

.amt-image-card{
  background:#fff;
  border:1px solid var(--amt-line);
  border-radius:var(--amt-card-radius);
  overflow:hidden;
  box-shadow:var(--amt-shadow);
  transition:transform .35s ease,box-shadow .35s ease,border-color .35s ease;
}

.amt-image-card:hover{
  transform:translateY(-5px);
  border-color:rgba(232,111,28,.28);
  box-shadow:0 22px 60px rgba(0,0,0,.09);
}

.amt-image-card img{
  width:100%;
  height:180px;
  object-fit:cover;
  display:block;
  transition:transform .45s ease;
}

.amt-image-card:hover img{
  transform:scale(1.04);
}

.amt-image-card p{
  margin:0;
  padding:18px;
  font-size:14px;
  line-height:1.6;
  color:#444;
}

/* FEATURES */

.amt-feature-grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:22px;
  margin-top:42px;
}

.amt-feature{
  padding:30px;
  border-radius:var(--amt-card-radius);
  background:#fff;
  border:1px solid var(--amt-line);
  box-shadow:var(--amt-shadow);
  transition:transform .35s ease,box-shadow .35s ease,border-color .35s ease;
}

.amt-feature:hover{
  transform:translateY(-5px);
  border-color:rgba(232,111,28,.28);
  box-shadow:0 22px 60px rgba(0,0,0,.09);
}

.amt-feature h3{
  margin:0 0 14px;
  font-size:24px;
}

.amt-feature p{
  margin:0;
  font-size:15px;
  line-height:1.8;
  color:#5b6370;
}

/* EXAMPLES */

.amt-example-grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:26px;
  margin-top:44px;
}

.amt-example{
  overflow:hidden;
  border-radius:var(--amt-card-radius);
  background:#fff;
  border:1px solid var(--amt-line);
  box-shadow:var(--amt-shadow);
  transition:transform .35s ease,box-shadow .35s ease,border-color .35s ease;
}

.amt-example:hover{
  transform:translateY(-5px);
  border-color:rgba(232,111,28,.28);
  box-shadow:0 22px 60px rgba(0,0,0,.09);
}

.amt-example img{
  width:100%;
  display:block;
  transition:transform .45s ease;
}

.amt-example:hover img{
  transform:scale(1.035);
}

.amt-example-body{
  padding:28px;
}

.amt-example-body h3{
  margin:0 0 12px;
  font-size:28px;
}

.amt-example-body p{
  margin:0;
  font-size:16px;
  line-height:1.8;
  color:#59606d;
}

/* DARK BLOCK */

.amt-dark{
  margin-top:90px;
  padding:56px;
  border-radius:30px;
  background:#121419;
  color:#fff;
  box-shadow:0 26px 70px rgba(0,0,0,.15);
}

.amt-dark h2{
  margin:0 0 22px;
  font-size:48px;
  line-height:1.08;
  font-weight:800;
}

.amt-dark p{
  margin:0;
  max-width:1100px;
  font-size:18px;
  line-height:1.95;
  color:#d7d9dd;
}

.amt-dark a{
  color:#ffb06d;
  text-decoration:none;
  font-weight:700;
}

/* ANIMATION */

@keyframes amtBarGrow{
  from{transform:scaleY(0);opacity:.35}
  to{transform:scaleY(1);opacity:1}
}

@keyframes amtProgressGrow{
  from{transform:scaleX(0)}
  to{transform:scaleX(1)}
}

@keyframes amtRadialGrow{
  from{--amt-radial-fill:0%}
  to{--amt-radial-fill:var(--amt-radial-value)}
}

@keyframes amtFadeUp{
  from{opacity:0;transform:translateY(8px)}
  to{opacity:1;transform:translateY(0)}
}

/* RESPONSIVE */

@media(max-width:1200px){
  .amt-graph-grid,
  .amt-process,
  .amt-image-grid{
    grid-template-columns:repeat(2,1fr);
  }
}

@media(max-width:1100px){
  .amt-hero,
  .amt-app-grid,
  .amt-feature-grid,
  .amt-example-grid{
    grid-template-columns:1fr;
  }

  .amt-title{
    font-size:50px;
  }

  .amt-hero-panel{
    min-height:480px;
  }
}

@media(max-width:768px){
  .amt-wrapper{
    padding:54px 16px;
  }

  .amt-title{
    font-size:40px;
    letter-spacing:-1.4px;
  }

  .amt-section-title,
  .amt-dark h2{
    font-size:34px;
  }

  .amt-graph-grid,
  .amt-process,
  .amt-image-grid{
    grid-template-columns:1fr;
  }

  .amt-dark{
    padding:34px 28px;
  }

  .amt-core{
    width:300px;
    padding:30px;
  }

  .amt-core-value{
    font-size:46px;
  }
}


